import{t as d,a1 as r,Z as a,a9 as n,cl as s,a8 as i,a7 as o,bs as l,be as c}from"./index-DErtGJ6x.js";const b={},h={class:"lesson-page"},f={class:"shell"},u={class:"pager","aria-label":"Tutorialnavigation"};function v(p,e){const t=l("RouterLink");return c(),r("main",h,[a("div",f,[n(t,{to:"/medientechnik/adobe-indesign/mini-tutorials",class:"back"},{default:s(()=>[...e[0]||(e[0]=[i("← Mini Tutorials",-1)])]),_:1}),e[2]||(e[2]=o('<header data-v-f94b7740><p class="eyebrow" data-v-f94b7740>ADOBE INDESIGN · MINI TUTORIAL</p><h1 data-v-f94b7740>Textrahmen automatisch an Text anpassen</h1><p class="goal" data-v-f94b7740>Dein Textrahmen wächst mit, wenn du den Inhalt oder die Schriftgestaltung veränderst.</p></header><section aria-labelledby="terms-title" data-v-f94b7740><h2 id="terms-title" data-v-f94b7740>Einfach erklärt</h2><dl data-v-f94b7740><div data-v-f94b7740><dt data-v-f94b7740>Automatische Größenänderung</dt><dd data-v-f94b7740>InDesign passt die Größe des Textrahmens an seinen Inhalt an. Du legst fest, welche Dimensionen sich ändern dürfen.</dd></div><div data-v-f94b7740><dt data-v-f94b7740>Bezugspunkt</dt><dd data-v-f94b7740>Dieser Punkt bleibt an seiner Position, wenn der Rahmen wächst oder schrumpft.</dd></div></dl></section><section class="practice" aria-labelledby="practice-title" data-v-f94b7740><h2 id="practice-title" data-v-f94b7740>So gehst du vor</h2><ol data-v-f94b7740><li data-v-f94b7740>Wähle deinen <strong data-v-f94b7740>Textrahmen</strong> aus.</li><li data-v-f94b7740>Gehe zu <strong data-v-f94b7740>Objekt → Textrahmenoptionen (⌘ + B)</strong>.</li><li data-v-f94b7740>Wechsle zum Reiter <strong data-v-f94b7740>Automatisch Größe ändern</strong>.</li><li data-v-f94b7740>Wähle bei <strong data-v-f94b7740>„Automatische Größenänderung“</strong> die Option <strong data-v-f94b7740>Nur Höhe</strong>.</li><li data-v-f94b7740>Wähle als Bezugspunkt <strong data-v-f94b7740>oben mittig</strong>, damit der Textrahmen nach unten wächst. Bestätige mit <strong data-v-f94b7740>OK</strong>.</li></ol><p data-v-f94b7740>Jetzt passt sich die Höhe des Textrahmens automatisch an den Inhalt an – auch wenn du Schriftgröße oder Zeilenabstand veränderst.</p></section><section class="practice" aria-labelledby="tip-title" data-v-f94b7740><h2 id="tip-title" data-v-f94b7740>Praktischer Tipp</h2><p data-v-f94b7740>Mit einem <strong data-v-f94b7740>Doppelklick auf einen Anfasser</strong> des Textrahmens kannst du den Rahmen auch einmalig an den Text anpassen.</p><p data-v-f94b7740>Ein Anfasser ist eines der <strong data-v-f94b7740>acht kleinen Quadrate am Rand des ausgewählten Rahmens</strong>.</p></section><section class="check" aria-labelledby="check-title" data-v-f94b7740><h2 id="check-title" data-v-f94b7740>Prüfe dein Ergebnis</h2><p data-v-f94b7740>Füge Text hinzu und verändere Schriftgröße oder Zeilenabstand. Wächst der Rahmen nach unten, während seine Breite und die obere Kante gleich bleiben?</p></section><section class="practice" aria-labelledby="example-title" data-v-f94b7740><h2 id="example-title" data-v-f94b7740>Beispieltext zum Ausprobieren</h2><p data-v-f94b7740>Dieser Text dient dazu, verschiedene Funktionen der Textgestaltung in Adobe InDesign auszuprobieren. Dabei können Schriftgröße, Zeilenabstand, Absatzabstände und die automatische Größenanpassung von Textrahmen getestet werden.</p></section>',6)),a("nav",u,[n(t,{to:"/medientechnik/adobe-indesign/mini-tutorials"},{default:s(()=>[...e[1]||(e[1]=[i("← Zur Übersicht",-1)])]),_:1})])])])}const m=d(b,[["render",v],["__scopeId","data-v-f94b7740"]]);export{m as default};
